{
  "expression": "div(gain, cost) + div(gain * rarity, cost * (cost + overlap))",
  "rationale": "Enhances the standard greedy benchmark div(gain, cost) by adding a tie-breaking/secondary term that prioritizes vertices covering rare (hard-to-cover) nodes while penalizing high overlap with already covered neighbors and higher relative cost."
}

{
  "expression": "div(gain, cost) + 0.5 * div(rarity, cost) - 0.2 * overlap",
  "rationale": "Enhances the standard greedy ratio gain/cost by incorporating vertex rarity per unit cost, giving higher priority to vertices covering hard-to-cover neighbors, while lightly penalizing overlap to reduce redundancy before the pruning phase."
}

{
  "expression": "div(gain, cost) + div(rarity, cost) - div(overlap, cost)",
  "rationale": "Extends the baseline greedy ratio gain/cost by incorporating vertex rarity to prioritize covering hard-to-cover vertices while penalizing closed-neighborhood overlap, all balanced by vertex cost."
}

{
  "expression": "div(gain, cost) + 0.35 * gain * rarity * (1.0 - overlap)",
  "rationale": "Enhances the greedy baseline div(gain, cost) by adding a secondary term that prioritizes candidates covering hard-to-cover vertices (high rarity) while minimizing redundant coverage within their own neighborhood (low overlap)."
}

{
  "expression": "div(gain, cost) + 0.35 * div(rarity, cost) - 0.15 * overlap",
  "rationale": "Prioritizes immediate coverage yield per unit cost while giving a secondary boost to vertices covering hard-to-reach (rare) uncovered neighbors, and slightly discounting candidates with high overlap redundancy."
}

{
  "expression": "div(gain, add(cost, 0.05))",
  "rationale": "Incorporating a small additive constant into the normalized cost smoothing prevents zero or near-zero cost vertices from disproportionately dominating the gain-to-cost ratio, encouraging more balanced coverage choices prior to the host pruning step."
}

{
  "expression": "div(gain, cost) + 0.35 * gain * rarity * (1.0 - overlap)",
  "rationale": "Enhances the greedy baseline by adding a secondary term that prioritizes candidate vertices covering rare, hard-to-cover vertices while favoring candidates with high internal efficiency (low overlap)."
}

{
  "expression": "div(gain, cost) + div(rarity, cost)",
  "rationale": "Combining efficiency (gain per cost) with structural urgency (rarity per cost) prioritizes candidates that efficiently cover hard-to-cover vertices early."
}

{
  "expression": "div(gain, cost) + 0.35 * div(rarity, cost) - 0.15 * overlap",
  "rationale": "Enhances the standard greedy ratio by prioritizing candidates that cover rare, hard-to-cover vertices while slightly penalizing overlapping coverage with already covered nodes."
}

{
  "expression": "div(gain, cost) + div(rarity, cost) - div(overlap, cost)",
  "rationale": "Extends the greedy baseline by adding a weighted penalty for redundant coverage (overlap) and a bonus for covering vertices with few potential dominant vertices (rarity), all normalized by vertex cost."
}

{
  "expression": "div(gain, add(cost, 0.001))",
  "rationale": "Refines the standard greedy ratio gain/cost by adding a small constant offset to cost, smoothing priority for very low-cost vertices that provide minimal coverage."
}

{
  "expression": "div(gain, cost) + div(gain * rarity, max(cost, 0.001)) - 0.2 * overlap",
  "rationale": "Combines efficiency (gain/cost) with coverage quality (rarity), favoring candidates that cover hard-to-cover vertices while penalizing high neighborhood overlap to reduce redundancy before pruning."
}
